#!/usr/bin/env bash
# Private Postfix PIPE adapter for the UnifyDesk Mail bounce transport.
# IMPORTANT: install only after staging QA and validating the example master.cf.
# The secrets live in a protected curl config file, never CLI arguments.
set -Eeuo pipefail
if [[ "$#" -ne 1 ]]; then
  echo "Missing VERP envelope recipient" >&2
  exit 64
fi
envelope="$1"
# Only ASCII bounce addresses generated by MailBounceAddress are permitted.
if [[ ! "$envelope" =~ ^ud\+[1-9][0-9]{0,18}\.[1-9][0-9]{0,18}\.[a-f0-9]{16}@[a-zA-Z0-9.-]{3,180}$ ]]; then
  echo "Invalid mail bounce envelope recipient" >&2
  exit 65
fi
conf=/etc/unifydesk-mail/feedback-curl.conf
if [[ ! -f "$conf" || ! -r "$conf" ]]; then
  echo "Dedicated private feedback credentials not installed" >&2
  exit 75
fi
# -T - streams stdin instead of buffering an arbitrary RFC 3464 report.
# Request is explicitly POST; no redirects/proxies and no successful exit for 4xx/5xx.
# The Spring endpoint enforces an independent 64KiB payload ceiling.
exec /usr/bin/curl --config "$conf" \
  --request POST --upload-file - \
  --header "X-UnifyDesk-Envelope-To: $envelope" \
  --header "Content-Type: message/rfc822" \
  --noproxy '*' --max-time 20 --connect-timeout 3 \
  --retry 0 --fail-with-body --silent --show-error
